import {Ajv} from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

function describeError(error: ErrorObject): string {
  const path = error.instancePath || '/';
  if (error.keyword === 'required') return `${path}: missing required property '${error.params.missingProperty}'`;
  return `${path}: ${error.message ?? error.keyword}`;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private compile(definition: ToolDefinition): ValidateFunction {
    try {
      return this.ajv.compile(definition.inputSchema);
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool ${definition.name}: ${reason}`, {cause: error});
    }
  }

  private validatorFor(tool: StoredTool): ValidateFunction {
    if (tool.validate) return tool.validate;
    const schema = this.resolveDefinition(tool.definitionSource).inputSchema;
    let validate = this.dynamicValidators.get(schema);
    if (!validate) {
      validate = this.compile(this.resolveDefinition(tool.definitionSource));
      this.dynamicValidators.set(schema, validate);
    }
    return validate;
  }

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validate = typeof definition === 'function' ? undefined : this.compile(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against inputSchema, then runs the tool; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = this.validatorFor(tool);
    if (!validate(input)) {
      const problems = (validate.errors ?? []).map(describeError);
      log.warn('tool', 'input rejected', {name, problems});
      return {result: `Invalid input for tool ${name}: ${problems.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('passes valid input with an unlisted extra property to the executor unchanged, exactly once', async () => {
    const registry = new ToolRegistry();
    const received: Record<string, unknown>[] = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async input => {
        received.push(input);
        return 'sunny';
      }
    );

    await registry.execute('get_weather', {location: 'Berlin', extra: 1});

    expect(received).toEqual([{location: 'Berlin', extra: 1}]);
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });

  describe('function-valued definition whose schema changes between calls', () => {
    const run = async () => {
      const registry = new ToolRegistry();
      let schema: Record<string, unknown> = {type: 'object', properties: {n: {type: 'string'}}, required: ['n']};
      const received: Record<string, unknown>[] = [];
      registry.register(
        () => ({name: 'dynamic_tool', description: 'Dynamic schema', inputSchema: schema}),
        async input => {
          received.push(input);
          return 'ok';
        }
      );

      await registry.execute('dynamic_tool', {n: 'a'});
      schema = {type: 'object', properties: {n: {type: 'number'}}, required: ['n']};
      const rejected = await registry.execute('dynamic_tool', {n: 'a'});
      await registry.execute('dynamic_tool', {n: 2});
      return {rejected, received};
    };

    it('validates a function-valued definition against the schema current at each call', async () => {
      const {rejected} = await run();

      expect(rejected.result).toContain('/n');
    });

    it('runs the executor only for input the current schema accepted', async () => {
      const {received} = await run();

      expect(received).toEqual([{n: 'a'}, {n: 2}]);
    });
  });

  it('reads a static definition inputSchema only at register time across ten executes', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const definition = {
      name: 'static_tool',
      description: 'Static schema',
      get inputSchema(): Record<string, unknown> {
        schemaReads += 1;
        return {type: 'object', properties: {n: {type: 'string'}}, required: ['n']};
      },
    };
    registry.register(definition, async () => 'ok');
    const readsAfterRegister = schemaReads;

    for (let call = 0; call < 10; call += 1) {
      await registry.execute('static_tool', {n: 'a'});
    }

    expect(schemaReads).toBe(readsAfterRegister);
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | Shipped              |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with an unlisted extra property to the executor unchanged, exactly once](../../src/orchestration/tools/registry.test.ts#L4)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake ([validated by: throws Unknown tool for an unregistered name](../../src/orchestration/tools/registry.test.ts#L24)).

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: reads a static definition inputSchema only at register time across ten executes](../../src/orchestration/tools/registry.test.ts#L63)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates a function-valued definition against the schema current at each call](../../src/orchestration/tools/registry.test.ts#L50), and the executor runs only for input the schema current at that call accepted ([validated by: runs the executor only for input the current schema accepted](../../src/orchestration/tools/registry.test.ts#L56)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
